from pathlib import Path
import json,subprocess,os,statistics
root=Path.cwd(); directory=root/'target/bench/optimization-followup/small-slice-final'; directory.mkdir(exist_ok=True)
template=json.loads((root/'target/bench/runtime-improvements-2026-10-23/short-loop-bounds/slice-derived-bounds.config.json').read_text())
workers={'before':root/'target/bench/optimization-followup/baseline/benchmark_dsp','after':root/'target/release/examples/benchmark_dsp'}
results=[]
for precision in ['f32','f64']:
 for size in [1,2,3,4,5,7,8,9,16,64,512]:
  source=directory/f'reverse-{precision}-{size}.onda'
  source.write_text(f'''outs<{precision}> 1
def reverse(src: {precision}[], dst: {precision}[]):
  for i in 0..min(src.len(), dst.len()):
    dst[i] = src[src.len() - 1 - i]
init:
  source: {precision}[{size}] = [{', '.join(str(i+1)+'.0' for i in range(size))}]
  destination: {precision}[{size}]
  frame = 0
sample:
  left = frame % {size+1}
  right = (frame / {size+1}) % {size+1}
  destination[:] = -9.0
  reverse(source[:left], destination[:right])
  error: {precision} = 0.0
  for i in 0..{size}:
    expected: {precision} = -9.0
    if i < min(left, right):
      expected = {precision}(left - i)
    error += abs(destination[i] - expected)
  out1 = error
  frame += 1
''')
  data={'precision':precision,'size':size,'runs':{w:[] for w in workers}}
  for pair in range(2):
   for name in (list(workers) if pair%2==0 else list(reversed(workers))):
    prefix=directory/f'{precision}-{size}-{pair}-{name}'
    config=dict(template,source=str(source),prefix=str(prefix),repetitions=7,round_ms=60,assembly=False,ir=False,max_output_abs=0.0)
    path=prefix.with_suffix('.config.json');path.write_text(json.dumps(config))
    run=subprocess.run(['taskset','-c','6',workers[name],path],env=dict(os.environ,RUST_MIN_STACK='67108864'),text=True,capture_output=True,timeout=30)
    prefix.with_suffix('.stdout.log').write_text(run.stdout);prefix.with_suffix('.stderr.log').write_text(run.stderr)
    if run.returncode:raise RuntimeError(run.stderr)
    data['runs'][name].append(json.loads(run.stdout)['ns_per_frame'])
  data['medians']={name:statistics.median(values) for name,values in data['runs'].items()};data['ratio']=data['medians']['after']/data['medians']['before'];results.append(data)
  (directory/'results.json').write_text(json.dumps(results,indent=2));print(precision,size,data['medians'],data['ratio'],flush=True)

