from pathlib import Path
import json,subprocess,statistics,hashlib
root=Path.cwd();base=root/'target/bench/optimization-followup';out=base/'fft-paired-final';out.mkdir(exist_ok=True)
results=[]
for size in [1024,4096]:
 for precision in ['f32','f64']:
  name=f'fft-{precision}-{size}'
  a=base/'fft-original'/name;runtime=json.loads((a/f'{name}.object.json').read_text())['runtime'];before=out/f'{name}-before'
  subprocess.run(['cc','-O3','-march=native','-ffp-contract=off','-no-pie','-Iinclude',f'-DFFT_SIZE={size}',f'-DFFT_SINGLE={int(precision=="f32")}',f'-DONDA_STATE_SIZE={runtime["state_size_bytes"]}',f'-DONDA_STATE_ALIGN={runtime["state_align_bytes"]}','scripts/bench/fft_reference.c',a/f'{name}.o','-lfftw3f','-lfftw3','-lm','-o',before],check=True)
  binaries={'before':before,'after':base/'fft-final'/f'{name}-bench'}
  for instances in [1,32,512]:
   row=dict(size=size,precision=precision,instances=instances,runs={key:[] for key in binaries})
   for pair in range(3):
    for key in (list(binaries) if pair%2==0 else list(reversed(binaries))):
     run=subprocess.run(['taskset','-c','6',binaries[key],str(instances),'7','40'],capture_output=True,text=True,timeout=60)
     prefix=out/f'{name}-{instances}-{pair}-{key}';prefix.with_suffix('.stderr.log').write_text(run.stderr);prefix.with_suffix('.stdout.log').write_text(run.stdout)
     if run.returncode:raise RuntimeError(run.stderr)
     row['runs'][key].append(json.loads(run.stdout))
   row['medians_ns_per_transform']={key:statistics.median(statistics.median(r['ns_per_transform'] for r in run['rounds'] if r['implementation']=='onda') for run in runs) for key,runs in row['runs'].items()}
   row['ratio']=row['medians_ns_per_transform']['after']/row['medians_ns_per_transform']['before']
   row['output_hashes_match']=len({run['onda_output_hash'] for runs in row['runs'].values() for run in runs})==1
   assert row['output_hashes_match'],row
   row['after_to_fftw']=statistics.median(statistics.median(r['ns_per_transform'] for r in run['rounds'] if r['implementation']=='onda')/statistics.median(r['ns_per_transform'] for r in run['rounds'] if r['implementation']=='fftw') for run in row['runs']['after'])
   results.append(row);(out/'results.json').write_text(json.dumps(results,indent=2))
   print(precision,size,instances,row['medians_ns_per_transform'],round(row['ratio'],3),round(row['after_to_fftw'],3),flush=True)
